{
  "findings": [
    {
      "check_id": "CKV_GCP_106",
      "title": "Unrestricted HTTP port 80 ingress",
      "resource": "google_compute_firewall.allow_http_https",
      "severity": "MEDIUM",
      "explanation": "The firewall permits TCP port 80 from 0.0.0.0/0, exposing unencrypted HTTP traffic to the entire internet. Removing port 80 ensures public web traffic uses the encrypted HTTPS endpoint."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http_https\" {\n  name    = \"digital-asset-trading-platform-firewall-web\"\n  network = google_compute_network.digital_asset_trading_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"443\", \"8080\"]\n  }\n  source_ranges = [\"0.0.0.0/0\"]\n  target_tags   = [\"web-server\"]\n}\n",
  "fix_summary": "Removed unrestricted ingress on TCP port 80 while retaining the existing HTTPS and application-port access."
}
